import {
  LiveKitRoom,
  VideoConference,
} from "@livekit/components-react";
import "@livekit/components-styles";

const LIVEKIT_URL = "wss://plataforma-clases-en-vivo-4xbfxixj.livekit.cloud";

// Puedes recibir el token por props o ponerlo fijo para pruebas.
// En producción, debes generarlo dinámicamente desde tu backend.

const LiveKitMeet = ({ roomName, userName, onLeave }) => {
  // Para pruebas, pega aquí tu token JWT generado en Node:
  const demoToken = "eyJhbGciOiJIUzI1NiJ9.eyJ2aWRlbyI6eyJyb29tSm9pbiI6dHJ1ZSwicm9vbSI6ImNsYXNlLXBydWViYS0xIn0sImlzcyI6IkFQSVJ4YjJEYktzc05xciIsImV4cCI6MTc0ODY0MTk5MywibmJmIjowLCJzdWIiOiJQcm9mZXNvckRlbW8ifQ.QgDYrkmjTX58dNUxLsbfHTiS3S6LoIk5RdqaAUwc8gQ";

  return (
    <div style={{ width: "100%", height: "700px" }}>
      <LiveKitRoom
        token={demoToken}
        serverUrl={LIVEKIT_URL}
        connect={true}
        data-lk-theme="default"
        style={{ height: "100%" }}
        onDisconnected={onLeave}
      >
        <VideoConference />
      </LiveKitRoom>
    </div>
  );
};

export default LiveKitMeet;
